FeatureScript 3070;
import(path : "onshape/std/common.fs", version : "3070.0");
import(path : "onshape/std/primitives.fs", version : "3070.0");

// Four-piece inverse mold proof of concept for fins generated by the current
// Fin Generator coordinate convention:
//   X = chordwise (leading edge toward smaller X)
//   Y = foil thickness
//   Z = span (the mounting base extends below the root plane)
//
// This first version intentionally creates only the major mold solids. It does
// not add draft, printed-fit compensation, alignment pins, clamp holes, vents,
// or resin bleed channels. Those details should be added after the four cavity
// bodies regenerate and can be virtually separated without interference.

export const MOLD_MARGIN_BOUNDS =
{
    (meter) : [0.002, 0.015, 0.100],
    (millimeter) : 15
} as LengthBoundSpec;

export const MOLD_WALL_BOUNDS =
{
    (meter) : [0.003, 0.012, 0.100],
    (millimeter) : 12
} as LengthBoundSpec;

export const MOLD_ROOT_Z_BOUNDS =
{
    (meter) : [-1, 0, 1],
    (millimeter) : 0
} as LengthBoundSpec;

export const MOLD_SPLIT_OFFSET_BOUNDS =
{
    (meter) : [-0.100, 0, 0.100],
    (millimeter) : 0
} as LengthBoundSpec;

export const MOLD_BASE_WIDTH_BOUNDS =
{
    (meter) : [0.003, 0.007, 0.050],
    (millimeter) : 7
} as LengthBoundSpec;

export const MOLD_PLUG_BORDER_BOUNDS =
{
    (meter) : [0.001, 0.006, 0.030],
    (millimeter) : 6
} as LengthBoundSpec;

export const MOLD_CAPTURE_DEPTH_BOUNDS =
{
    (meter) : [0.001, 0.005, 0.030],
    (millimeter) : 5
} as LengthBoundSpec;


// Subtract the selected fin from one mold blank while retaining the fin so it
// can cut the other three blanks and remain available for visual inspection.
function cutMoldCavity(
    context is Context,
    id is Id,
    blank is Query,
    finBody is Query)
{
    opBoolean(context, id, {
            "targets" : blank,
            "tools" : finBody,
            "operationType" : BooleanOperationType.SUBTRACTION,
            "keepTools" : true
    });
}


function getEdgeEndpoints(context is Context, edge is Query) returns map
{
    var vertices = evaluateQuery(context, qAdjacent(
        edge,
        AdjacencyType.VERTEX,
        EntityType.VERTEX
    ));

    if (size(vertices) != 2)
        throw regenError("Each selected parting edge must have two endpoints.");

    return {
        "point0" : evVertexPoint(context, { "vertex" : vertices[0] }),
        "point1" : evVertexPoint(context, { "vertex" : vertices[1] })
    };
}


// The leading and trailing edges meet at the tip. Find the closest endpoint
// pair rather than assuming a particular edge direction or relying on global Z.
function getPlanformReferencePoints(
    context is Context,
    leadingEdge is Query,
    trailingEdge is Query) returns map
{
    var le = getEdgeEndpoints(context, leadingEdge);
    var te = getEdgeEndpoints(context, trailingEdge);

    var bestDistance = norm(le.point0 - te.point0);
    var rootLE = le.point1;
    var rootTE = te.point1;
    var leadingTip = le.point0;
    var trailingTip = te.point0;

    var distance01 = norm(le.point0 - te.point1);
    if (distance01 < bestDistance)
    {
        bestDistance = distance01;
        rootLE = le.point1;
        rootTE = te.point0;
        leadingTip = le.point0;
        trailingTip = te.point1;
    }

    var distance10 = norm(le.point1 - te.point0);
    if (distance10 < bestDistance)
    {
        bestDistance = distance10;
        rootLE = le.point0;
        rootTE = te.point1;
        leadingTip = le.point1;
        trailingTip = te.point0;
    }

    var distance11 = norm(le.point1 - te.point1);
    if (distance11 < bestDistance)
    {
        bestDistance = distance11;
        rootLE = le.point0;
        rootTE = te.point0;
        leadingTip = le.point1;
        trailingTip = te.point1;
    }

    if (bestDistance > 0.5 * millimeter)
    {
        throw regenError(
            "The selected leading and trailing edges must meet at the fin tip.",
            ["leadingEdge", "trailingEdge"]
        );
    }

    return {
        "rootLE" : rootLE,
        "rootTE" : rootTE,
        "tip" : (leadingTip + trailingTip) / 2
    };
}


annotation {
    "Feature Type Name" : "Create Mold - 4 Piece POC",
    "Feature Type Description" :
        "Create two foil-side mold halves and two base inserts from a completed fin"
}
export const createFourPieceMold = defineFeature(function(
    context is Context,
    id is Id,
    definition is map)
    precondition
    {
        annotation {
            "Name" : "Completed fin body",
            "Filter" : EntityType.BODY && BodyType.SOLID,
            "MaxNumberOfPicks" : 1
        }
        definition.finBody is Query;

        annotation {
            "Name" : "Leading-edge seam",
            "Filter" : EntityType.EDGE,
            "MaxNumberOfPicks" : 1
        }
        definition.leadingEdge is Query;

        annotation {
            "Name" : "Trailing-edge seam",
            "Filter" : EntityType.EDGE,
            "MaxNumberOfPicks" : 1
        }
        definition.trailingEdge is Query;

        annotation { "Name" : "Root split Z" }
        isLength(definition.rootZ, MOLD_ROOT_Z_BOUNDS);

        annotation { "Name" : "Chordwise margin" }
        isLength(definition.chordMargin, MOLD_MARGIN_BOUNDS);

        annotation { "Name" : "Tip margin" }
        isLength(definition.tipMargin, MOLD_MARGIN_BOUNDS);

        annotation { "Name" : "Bottom margin" }
        isLength(definition.bottomMargin, MOLD_MARGIN_BOUNDS);

        annotation { "Name" : "Mold wall outside foil" }
        isLength(definition.sideWall, MOLD_WALL_BOUNDS);

        annotation { "Name" : "Base width" }
        isLength(definition.baseWidth, MOLD_BASE_WIDTH_BOUNDS);

        annotation { "Name" : "Base plug border" }
        isLength(definition.plugBorder, MOLD_PLUG_BORDER_BOUNDS);

        annotation {
            "Name" : "Fin-half overlap below body",
            "Description" :
                "How far the foil-side molds extend below the selected fin body's minimum Z"
        }
        isLength(definition.captureDepth, MOLD_CAPTURE_DEPTH_BOUNDS);

        annotation {
            "Name" : "Base hot-dog split offset",
            "Description" :
                "Moves the lengthwise split across the base thickness direction"
        }
        isLength(definition.baseSplitOffset, MOLD_SPLIT_OFFSET_BOUNDS);
    }
    {
        var selectedBodies = evaluateQuery(context, definition.finBody);
        if (size(selectedBodies) != 1)
        {
            throw regenError(
                "Select exactly one completed solid fin body.",
                ["finBody"]
            );
        }

        if (size(evaluateQuery(context, definition.leadingEdge)) != 1 ||
            size(evaluateQuery(context, definition.trailingEdge)) != 1)
        {
            throw regenError(
                "Select one continuous leading-edge seam and one continuous trailing-edge seam.",
                ["leadingEdge", "trailingEdge"]
            );
        }

        var finBox = evBox3d(context, {
                "topology" : definition.finBody,
                "tight" : true
        });

        var minX = finBox.minCorner[0];
        var maxX = finBox.maxCorner[0];
        var minY = finBox.minCorner[1];
        var maxY = finBox.maxCorner[1];
        var minZ = finBox.minCorner[2];
        var maxZ = finBox.maxCorner[2];

        if (definition.rootZ <= minZ || definition.rootZ >= maxZ)
        {
            throw regenError(
                "Root split Z must lie inside the selected fin body height. " ~
                "For the current Add Base tool the expected value is 0 mm.",
                ["rootZ"]
            );
        }

        if (definition.bottomMargin <= definition.captureDepth)
        {
            throw regenError(
                "Bottom margin must be greater than the fin-half overlap so " ~
                "the base plug remains exposed for insertion.",
                ["bottomMargin", "captureDepth"]
            );
        }

        // Build the actual foil center plane from the selected planform edges.
        // This follows fin cant and rake instead of assuming the global X-Z
        // plane or the center of an axis-aligned bounding box.
        var referencePoints = getPlanformReferencePoints(
            context,
            definition.leadingEdge,
            definition.trailingEdge
        );
        var rootLE = referencePoints.rootLE;
        var rootTE = referencePoints.rootTE;
        var tipPoint = referencePoints.tip;

        var chordVector = rootTE - rootLE;
        var spanVector = tipPoint - (rootLE + rootTE) / 2;
        if (norm(chordVector) < 0.1 * millimeter ||
            norm(spanVector) < 0.1 * millimeter)
        {
            throw regenError(
                "The selected edges do not define a usable root chord and span.",
                ["leadingEdge", "trailingEdge"]
            );
        }

        var chordDirection = normalize(chordVector);
        var spanDirection = normalize(spanVector);
        var partingNormal = cross(chordDirection, spanDirection);
        if (norm(partingNormal) < 0.000001)
        {
            throw regenError(
                "The selected edges produce a degenerate parting plane.",
                ["leadingEdge", "trailingEdge"]
            );
        }
        partingNormal = normalize(partingNormal);

        // cross(chord, span) also guarantees that the coordinate system's
        // in-plane Y axis points from the root toward the tip.
        var partingPlane = plane(rootLE, partingNormal, chordDirection);

        // ================================================================
        // BASE PLUGS — CREATED FIRST
        // The base is split lengthwise (hot-dog style) in the thickness
        // direction. Each piece therefore contains the full Futures-base
        // length and releases toward its respective foil-side mold.
        // ================================================================

        var baseCenterY = (rootLE[1] + rootTE[1]) / 2;
        var baseMinY = baseCenterY - definition.baseWidth / 2
            - definition.plugBorder;
        var baseMaxY = baseCenterY + definition.baseWidth / 2
            + definition.plugBorder;
        var baseSplitY = baseCenterY + definition.baseSplitOffset;

        if (baseSplitY <= baseMinY || baseSplitY >= baseMaxY)
        {
            throw regenError(
                "The base split offset places the split outside the plug. " ~
                "Reduce the offset.",
                ["baseSplitOffset"]
            );
        }

        var baseMinX = minX - definition.plugBorder;
        var baseMaxX = maxX + definition.plugBorder;
        var baseMinZ = minZ - definition.bottomMargin;

        fCuboid(context, id + "baseSideA", {
                "corner1" : vector(baseMinX, baseSplitY, baseMinZ),
                "corner2" : vector(baseMaxX, baseMaxY, definition.rootZ)
        });

        fCuboid(context, id + "baseSideB", {
                "corner1" : vector(baseMinX, baseMinY, baseMinZ),
                "corner2" : vector(baseMaxX, baseSplitY, definition.rootZ)
        });

        var baseSideABody = qCreatedBy(id + "baseSideA", EntityType.BODY);
        var baseSideBBody = qCreatedBy(id + "baseSideB", EntityType.BODY);

        cutMoldCavity(
            context,
            id + "cutBaseSideA",
            baseSideABody,
            definition.finBody
        );
        cutMoldCavity(
            context,
            id + "cutBaseSideB",
            baseSideBBody,
            definition.finBody
        );

        // ================================================================
        // FOIL-SIDE MOLDS
        // Start with two identical world-aligned envelopes and retain opposite
        // sides of the LE/TE parting plane. The internal seam follows fin cant,
        // while every external wall remains parallel to global X, Y, or Z for
        // straightforward fixturing.
        // ================================================================

        var sideMinX = minX - definition.chordMargin;
        var sideMaxX = maxX + definition.chordMargin;
        var sideMinY = minY - definition.plugBorder - definition.sideWall;
        var sideMaxY = maxY + definition.plugBorder + definition.sideWall;
        // Both offsets reference the selected body's minimum Z independently:
        // the base plugs extend by Bottom margin (15 mm default), while the
        // foil halves overlap them by only Capture depth (5 mm default).
        var sideMinZ = minZ - definition.captureDepth;
        var sideMaxZ = maxZ + definition.tipMargin;

        fCuboid(context, id + "foilSideA", {
                "corner1" : vector(sideMinX, sideMinY, sideMinZ),
                "corner2" : vector(sideMaxX, sideMaxY, sideMaxZ)
        });

        fCuboid(context, id + "foilSideB", {
                "corner1" : vector(sideMinX, sideMinY, sideMinZ),
                "corner2" : vector(sideMaxX, sideMaxY, sideMaxZ)
        });

        var sideABody = qCreatedBy(id + "foilSideA", EntityType.BODY);
        var sideBBody = qCreatedBy(id + "foilSideB", EntityType.BODY);

        opSplitPart(context, id + "splitFoilSideA", {
                "targets" : sideABody,
                "tool" : partingPlane,
                "keepType" : SplitOperationKeepType.KEEP_FRONT
        });
        opSplitPart(context, id + "splitFoilSideB", {
                "targets" : sideBBody,
                "tool" : partingPlane,
                "keepType" : SplitOperationKeepType.KEEP_BACK
        });

        cutMoldCavity(context, id + "cutFoilSideA", sideABody, definition.finBody);
        cutMoldCavity(context, id + "cutFoilSideB", sideBBody, definition.finBody);

        // Use a through-cutter with the same external footprint as the two
        // assembled base plugs. It begins below the mold envelope, so the plug
        // socket is open at the bottom instead of being a blind pocket.
        fCuboid(context, id + "baseSocketCutter", {
                "corner1" : vector(
                    baseMinX,
                    baseMinY,
                    sideMinZ - 1 * millimeter
                ),
                "corner2" : vector(
                    baseMaxX,
                    baseMaxY,
                    definition.rootZ
                )
        });
        var baseSocketCutter = qCreatedBy(
            id + "baseSocketCutter",
            EntityType.BODY
        );

        opBoolean(context, id + "openSocketFoilSideA", {
                "targets" : sideABody,
                "tools" : baseSocketCutter,
                "operationType" : BooleanOperationType.SUBTRACTION,
                "keepTools" : true
        });
        opBoolean(context, id + "openSocketFoilSideB", {
                "targets" : sideBBody,
                "tools" : baseSocketCutter,
                "operationType" : BooleanOperationType.SUBTRACTION,
                "keepTools" : false
        });

        // Stable body names make the four mold pieces easy to inspect, hide,
        // export, and test for virtual removal in the Part Studio.
        setProperty(context, {
                "entities" : sideABody,
                "propertyType" : PropertyType.NAME,
                "value" : "Mold - Foil Side A"
        });
        setProperty(context, {
                "entities" : sideBBody,
                "propertyType" : PropertyType.NAME,
                "value" : "Mold - Foil Side B"
        });
        setProperty(context, {
                "entities" : baseSideABody,
                "propertyType" : PropertyType.NAME,
                "value" : "Mold - Base Plug A"
        });
        setProperty(context, {
                "entities" : baseSideBBody,
                "propertyType" : PropertyType.NAME,
                "value" : "Mold - Base Plug B"
        });
    });
